Lemma rdn_Wn_other : forall n M a v b m,
  0 <= a -> a + Z.of_nat n < 2 ^ 64 -> 0 <= b -> b + Z.of_nat m < 2 ^ 64 -> apart a (Z.of_nat n) b (Z.of_nat m) ->
